<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IP4_ADDR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">ipaddr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, LWIP_LOCAL_IP0, LWIP_LOCAL_IP1, LWIP_LOCAL_IP2, LWIP_LOCAL_IP3);</span></span>
